def count_terms(target, min_exp, max_exp, transform_func):
    ways = [0] * (target + 1)
    ways[0] = 1

    for exp in range(min_exp, max_exp + 1):
        for i in range(target, exp - 1, -1):
            ways[i] += ways[i - exp]

    transformed_target = transform_func(target)
    transformed_count = sum(ways[j] for j in range(min(transformed_target + 1, target + 1)))
    return transformed_count

